// art.py and flowers.py, for the code panes that type them out (made from the python files)
window.FY_SOURCES = {"art": "#!/usr/bin/env python3\n\"\"\"\nart.py - plays a video as living ASCII art, right inside the terminal.\n\n    python art.py                   plays the edit from this folder (the copy sign.py signed, if it's there)\n    python art.py clip.mp4          ...or any other video\n    python art.py --look pixels     sharp colour pixels instead of glyphs\n    python art.py --no-code         just the art, no code pane\n\nkeys while it runs:   q quit    m switch look    c show / hide the code\n\nneeds numpy + ffmpeg:   pip install numpy imageio-ffmpeg\nbest in a 24-bit colour terminal: Windows Terminal, VS Code, iTerm2, kitty, WezTerm\n\"\"\"\n\nfrom __future__ import annotations\n\nimport argparse\nimport builtins\nimport io\nimport keyword\nimport os\nimport queue\nimport re\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nimport threading\nimport time\nimport tokenize\n\nimport numpy as np\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nEDIT = next((p for p in (os.path.join(HERE, \"feelings_for_you.mp4\"), os.path.join(HERE, \"feelings.mp4\"))\n             if os.path.isfile(p)), os.path.join(HERE, \"feelings.mp4\"))      # the signed copy (sign.py) first\nSX, SY = 4, 8           # every terminal cell samples a 4 x 8 patch of the frame\nCROP = 0.97             # trim a hair off the edges (edits often carry a 1px border)\n\n\n# ── glyphs ──────────────────────────────────────────────────────────────────\n# how much of each of the 4x8 sub-cells a character covers (0-f), measured\n# from a monospace font. matching the picture against these is what puts a\n# \"/\" on a slanted edge, a \"_\" on a floor and an \"@\" in solid ink.\nGLYPHS = [\n    (\" \", \"00000000000000000000000000000000\"),\n    (\"`\", \"15000310000000000000000000000000\"),\n    (\".\", \"00000000000000000530053000000000\"),\n    (\"'\", \"03300650011000000000000000000000\"),\n    (\"-\", \"00000000000019900000000000000000\"),\n    (\":\", \"00000000076000000330043000000000\"),\n    (\"_\", \"00000000000000000000000088880000\"),\n    (\",\", \"00000000000000000430057028200000\"),\n    ('\"', \"15502990011000000000000000000000\"),\n    (\"^\", \"01100870546300000000000000000000\"),\n    (\"~\", \"00000000110089691041000000000000\"),\n    (\";\", \"00000000076000000430058018200000\"),\n    (\"<\", \"00000020058049000760004000000000\"),\n    (\">\", \"00001200184000930760240000000000\"),\n    (\"!\", \"03200650054005400320043000000000\"),\n    (\"=\", \"00000000355223314884000000000000\"),\n    (\"/\", \"00220080017007200900540030000000\"),\n    (\"*\", \"02203992388202200000000000000000\"),\n    (\"\\\\\", \"32002800091003600080006300120000\"),\n    (\"+\", \"0000000005407bb60540022000000000\"),\n    (\"?\", \"072001a1029209300500061000000000\"),\n    (\"|\", \"05400540054005400540054005400000\"),\n    (\")\", \"06000740009000900090036009000000\"),\n    (\"(\", \"005004600a000a000b00083001800000\"),\n    (\"]\", \"07500080008000800080008007900000\"),\n    (\"7\", \"23314797008102800920160000000000\"),\n    (\"}\", \"26100450026000b30260036029300000\"),\n    (\"{\", \"0161063007204b000820072004910000\"),\n    (\"[\", \"06600a000a000a000a000a000b600000\"),\n    (\"#\", \"011009615bb6388168a3224000000000\"),\n    (\"8\", \"02105894578339a29247287100000000\"),\n    (\"%\", \"45057963677008754579507400000000\"),\n    (\"0\", \"011049a390899a3a8456187000000000\"),\n    (\"$\", \"00504ab1875009b218575c7004000000\"),\n    (\"&\", \"174064904b60887891b6395700000000\"),\n    (\"@\", \"04615418758879888998754256600000\"),\n]\nRAMP = \" .-:;~=*+?{[#8%0$&@\"   # the glyphs that read as an even tone, light to dense\n\nCHARS = np.array([c for c, _ in GLYPHS])\nSHAPE = np.array([[int(d, 16) / 15 for d in bits] for _, bits in GLYPHS], np.float32)\nSHAPE_E = (SHAPE ** 2).sum(1)\nCOVER = SHAPE.mean(1)\n_ramp = np.array([CHARS.tolist().index(c) for c in RAMP])\nTONE = _ramp[np.abs(COVER[_ramp][None, :] - np.linspace(0, COVER.max(), 256)[:, None]).argmin(1)]\n\n\n# ── colours ─────────────────────────────────────────────────────────────────\ndef rgb(r, g, b):\n    return (r << 16) | (g << 8) | b\n\n\nC_TEXT, C_KEYWORD, C_FUNC = rgb(206, 206, 214), rgb(255, 95, 140), rgb(255, 186, 112)\nC_STRING, C_NUMBER, C_COMMENT = rgb(150, 214, 160), rgb(186, 152, 255), rgb(104, 104, 118)\nC_OP, C_NAME, C_LINENO = rgb(150, 150, 162), rgb(120, 196, 255), rgb(72, 72, 84)\nC_HILITE, C_BAR, C_HUD = rgb(46, 10, 22), rgb(255, 70, 122), rgb(150, 150, 162)\nC_PINK, C_RULE, C_STATUS = rgb(255, 92, 138), rgb(30, 30, 38), rgb(196, 196, 204)\nBUILTINS = set(dir(builtins)) | {\"self\", \"np\"}\n\n\ndef pack(c):\n    \"\"\"float rgb, channels first (3, ...) -> one int per colour, 32 steps a channel.\"\"\"\n    q = np.minimum(255, ((np.clip(c, 0, 1) * 255).astype(np.int32) + 4) >> 3 << 3)\n    return (q[0] << 16) | (q[1] << 8) | q[2]\n\n\ndef dim(c, f):\n    \"\"\"scale packed colour(s) towards black.\"\"\"\n    if f >= 1:\n        return c\n    c = np.asarray(c)\n    return (((c >> 16 & 255) * f).astype(np.int32) << 16 | ((c >> 8 & 255) * f).astype(np.int32) << 8\n            | ((c & 255) * f).astype(np.int32))\n\n\n# ── the art ─────────────────────────────────────────────────────────────────\n# each terminal cell looks at its own patch of the frame. we find the colour of\n# the page, wipe it to black, and redraw whatever is left as glyphs: solid ink\n# becomes dense letters, edges get the glyph whose shape fits them best.\n# tone and colour come from a quick 2x4 sample of every cell; only the cells\n# that hold an edge are looked at closely (4x8) to pick the glyph's shape.\ndef smoothstep(a, b, x):\n    t = np.clip((x - a) * (1 / (b - a)), 0.0, 1.0)\n    s = t * t\n    t *= -2\n    t += 3\n    s *= t\n    return s\n\n\ndef page_colour(r, g, b):\n    \"\"\"the most common colour in the frame - the paper everything sits on.\"\"\"\n    key = ((r * 15.99).astype(np.int32) << 8) | ((g * 15.99).astype(np.int32) << 4) | (b * 15.99).astype(np.int32)\n    counts = np.bincount(key.ravel(), minlength=4096)\n    top = counts.argmax()\n    hit = key == top\n    return (r[hit].mean(), g[hit].mean(), b[hit].mean()), float(counts[top] / key.size)\n\n\ndef glow(colour, pop):\n    \"\"\"lift colours so they shine on black; dark ink from a light page turns bright.\"\"\"\n    v = colour.max(0)\n    target = 0.42 + 0.58 * np.maximum(v, pop) ** 0.8\n    gain = target / np.maximum(v, 0.12)\n    out = colour * gain + np.maximum(0.0, target - v * gain)\n    grey = out.mean(0)\n    return np.clip(grey + (out - grey) * 1.25, 0.0, 1.0)\n\n\nclass Ink:\n    \"\"\"the rose look: the page goes black and everything on it turns to glyphs.\"\"\"\n\n    def __init__(self):\n        self.graphic = 1.0       # 1 = flat graphic frame, 0 = photo (smoothed)\n        self.grain = self.page = self.span = None\n\n    def coverage(self, R, G, B):\n        \"\"\"how much ink each sample holds (0-1), and how far it sits from the page colour.\"\"\"\n        g, p, dist = self.graphic, None, None\n        if g > 0.02:                                  # graphics: whatever isn't page\n            dr, dg, db = R - self.page[0], G - self.page[1], B - self.page[2]\n            dist = np.sqrt(dr * dr + dg * dg + db * db)\n            p = smoothstep(0.08, 0.55, dist)          # faint tints stay light, bold ink goes dense\n        if g < 0.98:                                  # photos: light becomes density\n            lo, hi = self.span\n            shade = np.clip((0.299 * R + 0.587 * G + 0.114 * B - lo) * (1 / (hi - lo)), 0.0, 1.0)\n            p = shade if p is None else g * p + (1 - g) * shade\n        return p, dist\n\n    def __call__(self, small, full):\n        R, G, B = small                               # (8, cells): a 2x4 sample of every cell\n        n = R.shape[1]\n        if self.grain is None or len(self.grain) != n:\n            self.grain = np.random.default_rng(22).uniform(0.72, 1.0, n).astype(np.float32)\n        self.page, share = page_colour(R[::2, ::2], G[::2, ::2], B[::2, ::2])\n        self.graphic += (float(smoothstep(0.10, 0.28, share)) - self.graphic) * 0.5\n        if self.graphic < 0.98:\n            lum = (0.299 * R[::3] + 0.587 * G[::3] + 0.114 * B[::3]).ravel()\n            k = len(lum) // 50\n            lo, hi = (float(v) for v in np.partition(lum, (k, len(lum) - 1 - k))[[k, len(lum) - 1 - k]])\n            self.span = (lo, max(hi, lo + 0.05))\n        p, dist = self.coverage(R, G, B)\n\n        total = p.sum(0)\n        mean = total * (1 / len(p))\n        glyph = TONE[np.clip(mean * self.grain * 255, 0, 255).astype(np.int32)]\n        edge = np.flatnonzero((p * p).sum(0) * (1 / len(p)) - mean * mean > 0.03)   # cells holding an outline\n        if len(edge):\n            cols = full.shape[2] // SX\n            er, ec = np.divmod(edge, cols)\n            patch = full.reshape(3, -1, SY, cols, SX)[:, er, :, ec, :]       # (edges, 3, 8, 4)\n            fine = patch.transpose(1, 2, 3, 0).reshape(3, SY * SX, len(edge)) * np.float32(1 / 255)\n            P, _ = self.coverage(fine[2], fine[0], fine[1])                  # planes come as g, b, r\n            glyph[edge] = (SHAPE_E[:, None] - 2 * SHAPE @ (0.82 * P)).argmin(0)\n\n        w = p + 0.02\n        colour = np.stack([(R * w).sum(0), (G * w).sum(0), (B * w).sum(0)]) / w.sum(0)\n        pop = 0.0\n        if dist is not None:\n            pop = self.graphic * np.clip((dist * p).sum(0) / np.maximum(total, 1e-3) * 2, 0, 1)\n        return glyph, pack(glow(colour, pop))\n\n\ndef pixels(small):\n    \"\"\"the hi-fi look: '▀' with the top half as ink and the bottom half as paper.\"\"\"\n    half = small.shape[1] // 2\n    return pack(small[:, :half].mean(1)), pack(small[:, half:].mean(1))\n\n\ndef to_cells(planes, sx, sy, scale=1 / 255):\n    \"\"\"ffmpeg's planar (g, b, r) values -> (3, sx*sy, rows*cols) floats in r, g, b order:\n    every cell's patch as a column, one plane per channel (numpy likes it that way round).\"\"\"\n    _, h, w = planes.shape\n    r, c = h // sy, w // sx\n    out = np.empty((3, sy, sx, r, c), np.float32)\n    for dst, src in ((0, 2), (1, 0), (2, 1)):\n        patch = planes[src, : r * sy, : c * sx].reshape(r, sy, c, sx).transpose(1, 3, 0, 2)\n        np.multiply(patch, np.float32(scale), out=out[dst])\n    return out.reshape(3, sy * sx, r * c)\n\n\ndef area_mean(a, h, w):\n    \"\"\"box-filter a picture down to h x w (every output pixel is the mean of its patch).\"\"\"\n    H, W = a.shape\n    ys, xs = np.linspace(0, H, h + 1).astype(int), np.linspace(0, W, w + 1).astype(int)\n    c = np.pad(a.cumsum(0).cumsum(1), ((1, 0), (1, 0)))\n    total = (c[ys[1:, None], xs[None, 1:]] - c[ys[:-1, None], xs[None, 1:]]\n             - c[ys[1:, None], xs[None, :-1]] + c[ys[:-1, None], xs[None, :-1]])\n    return total / np.maximum((ys[1:] - ys[:-1])[:, None] * (xs[1:] - xs[:-1])[None, :], 1)\n\n\nclass Signature:\n    \"\"\"your @ (signature.npz, made by sign.py), drawn big when the edit reaches its closing card.\n    at glyph size the card's own lettering is a smudge, so the name is set in big glyph letters\n    and moves exactly as the card does: up from below, two flashes, a bounce, then it settles.\"\"\"\n\n    HOT, BLUSH = np.array([255, 64, 129]) / 255, np.array([255, 196, 214]) / 255\n\n    def __init__(self, path):\n        with np.load(path) as z:\n            self.alpha = z[\"alpha\"] / 255.0\n            self.name = str(z[\"name\"])\n            self.start = float(z[\"start\"]) if \"start\" in z.files else 37.27     # when the card comes up\n            self.track = z[\"track\"] if \"track\" in z.files else np.zeros((1, 3))  # seconds, offset, flash\n        self.tall = self.alpha.shape[0] / self.alpha.shape[1]\n        self.cache = {}\n\n    def glyphs(self, cols):\n        if cols not in self.cache:\n            rows = max(2, round(cols * self.tall / 2))                    # cells are twice as tall as wide\n            cells = area_mean(self.alpha, rows * SY, cols * SX).reshape(rows, SY, cols, SX)\n            cells = cells.transpose(0, 2, 1, 3).reshape(rows * cols, SY * SX)\n            glyph = TONE[np.clip(cells.mean(1) * 255, 0, 255).astype(int)]\n            glyph[cells.mean(1) > 0.85] = CHARS.tolist().index(\"@\")      # solid strokes: one steady letter\n            edge = cells.std(1) > 0.2\n            glyph[edge] = (SHAPE_E - 2 * (0.82 * cells[edge]) @ SHAPE.T).argmin(1)\n            self.cache[cols] = (glyph.reshape(rows, cols), cells.mean(1).reshape(rows, cols))\n        return self.cache[cols]\n\n    def draw(self, scr, box, age):\n        x0, y0, w, h = box\n        scr.ch[y0: y0 + h, x0: x0 + w], scr.fg[y0: y0 + h, x0: x0 + w], scr.bg[y0: y0 + h, x0: x0 + w] = \" \", 0, 0\n        glyph, cover = self.glyphs(max(12, min(int(w * 0.92), int(h * 1.1 / self.tall))))\n        rows, cols = glyph.shape\n        i = int(np.clip(np.searchsorted(self.track[:, 0], age, \"right\") - 1, 0, len(self.track) - 1))\n        _, off, flash = self.track[i]\n        x, y = x0 + (w - cols) // 2, y0 + (h - rows) // 2 + int(round(off / CROP * h))\n        ys, xs = np.nonzero(glyph > 0)\n        fx = xs / max(cols - 1, 1)\n        if flash:                                                # the card's flashes: white-hot\n            colour = np.tile((self.BLUSH * 0.4 + 0.6)[:, None], len(xs))\n        else:\n            colour = (self.HOT[:, None] * (1 - fx * 0.85) + self.BLUSH[:, None] * fx * 0.85) * (0.62 + 0.38 * cover[ys, xs])\n            band = ((age - 1.0) * 0.4) % 2.2 - 0.4               # once it has settled, a slow shine\n            colour = colour + 0.33 * np.exp(-((fx - band + 0.15 * ys / max(rows - 1, 1)) / 0.05) ** 2) * (age > 1.0)\n        cy, cx = y + ys, x + xs\n        ok = (cy >= y0) & (cy < y0 + h) & (cx >= x0) & (cx < x0 + w)\n        scr.ch[cy[ok], cx[ok]] = CHARS[glyph[ys[ok], xs[ok]]]\n        scr.fg[cy[ok], cx[ok]] = pack(np.clip(colour[:, ok] * min(1.0, 0.55 + age / 0.2), 0, 1))\n\n\nclass Stars:\n    \"\"\"a slow twinkle in the empty black, like the sky behind the rose.\"\"\"\n\n    TINTS = np.array([[1.0, 1.0, 1.0], [1.0, 0.78, 0.88], [0.78, 0.86, 1.0]], np.float32)\n\n    def __init__(self):\n        self.size = None\n\n    def place(self, w, h):\n        rng = np.random.default_rng(5)\n        n = max(8, w * h // 55)\n        self.x, self.y = rng.integers(0, w, n), rng.integers(0, h, n)\n        self.phase, self.speed = rng.uniform(0, 6.283, n), rng.uniform(0.5, 2.2, n)\n        tint = self.TINTS[rng.integers(0, 3, n)].T[:, :, None]          # (3, stars, 1)\n        steps = np.arange(7, dtype=np.float32) / 6                       # brightness in 7 steps\n        self.colour = pack(tint * (0.18 + 0.72 * steps))                 # (stars, 7)\n        self.glint = np.flatnonzero(rng.random(n) < 0.1)\n        self.arm = pack(tint[:, self.glint, 0] * 0.35)\n        self.size = (w, h)\n\n    def draw(self, scr, x0, y0, w, h, t):\n        if self.size != (w, h):\n            self.place(w, h)\n        step = np.rint((0.5 + 0.5 * np.sin(self.speed * t + self.phase)) * 6).astype(np.int32)\n        xs, ys = self.x + x0, self.y + y0\n        lit = (step >= 3) & (scr.ch[ys, xs] == \" \") & (scr.bg[ys, xs] == 0)\n        s = step[lit]\n        scr.ch[ys[lit], xs[lit]] = np.where(s == 6, \"*\", np.where(s == 5, \"+\", \".\"))\n        scr.fg[ys[lit], xs[lit]] = self.colour[lit, s]\n        for k in np.flatnonzero(lit[self.glint] & (step[self.glint] == 6)).tolist():   # a cross of light\n            x, y = int(xs[self.glint[k]]), int(ys[self.glint[k]])\n            for dx, dy, c in ((-1, 0, \"-\"), (1, 0, \"-\"), (0, -1, \"|\"), (0, 1, \"|\")):\n                xx, yy = x + dx, y + dy\n                if x0 <= xx < x0 + w and y0 <= yy < y0 + h and scr.ch[yy, xx] == \" \" and not scr.bg[yy, xx]:\n                    scr.ch[yy, xx], scr.fg[yy, xx] = c, self.arm[k]\n\n\n# ── the code pane ───────────────────────────────────────────────────────────\nclass Code:\n    \"\"\"types this very file out, line by line, while the art plays.\"\"\"\n\n    def __init__(self, path, cps):\n        try:\n            with open(path, encoding=\"utf-8\") as f:\n                src = f.read()\n        except OSError:\n            src = \"\"\n        self.lines = src.split(\"\\n\")\n        self.paint = [np.full(len(line), C_TEXT, np.int32) for line in self.lines]\n        self._highlight(src)\n        self.starts = np.cumsum([0] + [len(line) + 1 for line in self.lines])\n        self.total = max(1, int(self.starts[-1]))\n        mark = next((i for i, line in enumerate(self.lines) if line.startswith(\"# ── the art\")), 0)\n        self.begin, self.cps = int(self.starts[mark]), cps\n\n    def _highlight(self, src):\n        strings = {tokenize.STRING} | {getattr(tokenize, k) for k in (\n            \"FSTRING_START\", \"FSTRING_MIDDLE\", \"FSTRING_END\",\n            \"TSTRING_START\", \"TSTRING_MIDDLE\", \"TSTRING_END\") if hasattr(tokenize, k)}\n        prev = \"\"\n        try:\n            for tok in tokenize.generate_tokens(io.StringIO(src).readline):\n                kind, text, colour = tok.type, tok.string, None\n                if kind == tokenize.COMMENT:\n                    colour = C_COMMENT\n                elif kind in strings:\n                    colour = C_STRING\n                elif kind == tokenize.NUMBER:\n                    colour = C_NUMBER\n                elif kind == tokenize.OP:\n                    colour = C_OP\n                elif kind == tokenize.NAME:\n                    colour = (C_KEYWORD if keyword.iskeyword(text) else C_FUNC if prev in (\"def\", \"class\")\n                              else C_NAME if text in BUILTINS else None)\n                if kind in (tokenize.NAME, tokenize.OP):\n                    prev = text\n                if colour is not None:\n                    (r0, c0), (r1, c1) = tok.start, tok.end\n                    for r in range(r0, r1 + 1):\n                        line = self.paint[r - 1]\n                        line[c0 if r == r0 else 0: c1 if r == r1 else len(line)] = colour\n        except (tokenize.TokenError, SyntaxError, IndexError):\n            pass\n\n    def draw(self, scr, x, y, w, h, t):\n        if w < 14 or h < 1:\n            return\n        pos = (self.begin + int(t * self.cps)) % self.total\n        line = int(np.searchsorted(self.starts, pos, side=\"right\")) - 1\n        col = pos - int(self.starts[line])\n        top, cx, room = line - int(h * 0.62), x + 7, w - 8\n        for r in range(h):\n            n = top + r\n            if n < 0 or n > line:\n                continue\n            here, row = n == line, y + r\n            bg = C_HILITE if here else 0\n            fade = min(1.0, (r + 1) / 4)                    # older lines melt into the dark\n            if here:\n                scr.fill(x, row, w, bg)\n                scr.put(x, row, \"▌\", C_BAR, bg)\n            scr.put(x + 1, row, f\"{n + 1:>4}\", C_BAR if here else dim(C_LINENO, fade), bg)\n            text = self.lines[n][: col if here else None][:room]\n            if text:\n                scr.put(cx, row, text, dim(self.paint[n][: len(text)], fade), bg)\n            if here:\n                scr.put(min(cx + len(text), x + w - 1), row, \" \", 0, C_BAR)   # the cursor\n\n\n# ── the screen ──────────────────────────────────────────────────────────────\ndef near(a, b, tol=24):\n    \"\"\"packed colours within a small step of each other.\"\"\"\n    d = np.abs((a >> 16 & 255) - (b >> 16 & 255))\n    d += np.abs((a >> 8 & 255) - (b >> 8 & 255))\n    d += np.abs((a & 255) - (b & 255))\n    return d <= tol\n\n\nCUBE = np.array([0, 95, 135, 175, 215, 255])\nEDGES = np.array([47, 115, 155, 195, 235])\n\n\ndef xterm256(c):\n    \"\"\"packed rgb -> the nearest of the 256 classic terminal colours (a 6x6x6 cube + 24 greys).\"\"\"\n    r, g, b = c >> 16 & 255, c >> 8 & 255, c & 255\n    ri, gi, bi = np.searchsorted(EDGES, r), np.searchsorted(EDGES, g), np.searchsorted(EDGES, b)\n    level = np.clip(((r + g + b) // 3 - 3) // 10, 0, 23)\n    v = 8 + 10 * level\n    off_cube = (r - CUBE[ri]) ** 2 + (g - CUBE[gi]) ** 2 + (b - CUBE[bi]) ** 2\n    chroma = np.maximum(np.maximum(r, g), b) - np.minimum(np.minimum(r, g), b)\n    off_grey = np.where(chroma < 40, (r - v) ** 2 + (g - v) ** 2 + (b - v) ** 2, 1 << 30)   # greys only for greys\n    return np.where(off_grey < off_cube, 232 + level, 16 + 36 * ri + 6 * gi + bi)\n\n\nclass Screen:\n    \"\"\"a grid of (glyph, ink, paper). only the cells that changed get re-sent.\"\"\"\n\n    def __init__(self, w, h, colours=24):\n        self.w, self.h, self.colours = w, h, colours\n        self.ch = np.full((h, w), \" \", dtype=\"<U1\")\n        self.fg = np.zeros((h, w), np.int32)\n        self.bg = np.zeros((h, w), np.int32)\n        self.prev = None\n\n    def clear(self):\n        self.ch[:], self.fg[:], self.bg[:] = \" \", 0, 0\n\n    def put(self, x, y, text, fg, bg=None):\n        if not 0 <= y < self.h or x >= self.w or x < 0:\n            return\n        text = text[: self.w - x]\n        n = len(text)\n        self.ch[y, x: x + n] = list(text)\n        self.fg[y, x: x + n] = fg if np.ndim(fg) == 0 else fg[:n]\n        if bg is not None:\n            self.bg[y, x: x + n] = bg\n\n    def fill(self, x, y, w, bg):\n        if 0 <= y < self.h:\n            self.ch[y, x: x + w], self.bg[y, x: x + w] = \" \", bg\n\n    def flush(self):\n        \"\"\"the escape codes that turn the last frame on screen into this one.\"\"\"\n        ch, fg, bg = self.ch, self.fg, self.bg\n        if self.colours == 256:\n            fg, bg = xterm256(fg), xterm256(bg)\n        if self.prev is None:\n            dirty = np.ones(ch.shape, bool)\n        else:                                         # a colour that barely moved isn't worth resending\n            pch, pfg, pbg = self.prev\n            same_fg, same_bg = (near(fg, pfg), near(bg, pbg)) if self.colours == 24 else (fg == pfg, bg == pbg)\n            dirty = (ch != pch) | ~same_bg | (~same_fg & (ch != \" \"))\n            fg, bg = np.where(dirty, fg, pfg), np.where(dirty, bg, pbg)\n        self.prev = (ch.copy(), fg.copy(), bg.copy())\n\n        # runs of changed cells across the whole screen at once; gaps under 10 cells are\n        # cheaper to resend than to jump over, so neighbouring runs on a row get merged\n        edges = np.diff(np.pad(dirty, ((0, 0), (1, 1))).view(np.int8), axis=1)\n        ys, a = np.nonzero(edges == 1)\n        b = np.nonzero(edges == -1)[1]\n        if not len(ys):\n            return \"\"\n        new = np.r_[True, (ys[1:] != ys[:-1]) | (a[1:] - b[:-1] > 10)]\n        first = np.flatnonzero(new)\n        last = np.r_[first[1:] - 1, len(ys) - 1]\n\n        out, cf, cb = [\"\\x1b[?2026h\"], -1, -1\n        fgs, bgs = (FG_SGR, BG_SGR) if self.colours == 24 else (FG_256, BG_256)\n        for y, x0, x1 in zip(ys[first].tolist(), a[first].tolist(), b[last].tolist()):\n            out.append(f\"\\x1b[{y + 1};{x0 + 1}H\")\n            for c, f, k in zip(ch[y, x0:x1].tolist(), fg[y, x0:x1].tolist(), bg[y, x0:x1].tolist()):\n                if k != cb:                                       # colour codes only on change\n                    out.append(bgs.get(k) or bgs.setdefault(k, f\"\\x1b[48;2;{k >> 16};{k >> 8 & 255};{k & 255}m\"))\n                    cb = k\n                if f != cf and c != \" \":\n                    out.append(fgs.get(f) or fgs.setdefault(f, f\"\\x1b[38;2;{f >> 16};{f >> 8 & 255};{f & 255}m\"))\n                    cf = f\n                out.append(c)\n        out.append(\"\\x1b[?2026l\")\n        return \"\".join(out)\n\n\nFG_SGR, BG_SGR = {}, {}          # escape codes we've already built, by colour\nFG_256 = {i: f\"\\x1b[38;5;{i}m\" for i in range(256)}\nBG_256 = {i: f\"\\x1b[48;5;{i}m\" for i in range(256)}\n\n\nclass Layout:\n    \"\"\"art on top and code below (tall windows), or side by side (wide ones).\"\"\"\n\n    def __init__(self, W, H, aspect, code, cell):\n        def fit(bw, bh):\n            vw = max(1, min(bw, int(bh * aspect * cell)))\n            vh = max(1, min(bh, int(vw / (aspect * cell) + 0.5)))\n            return vw, vh\n\n        options = []\n        if code:\n            hc = max(7, int(H * 0.36))\n            if H - hc - 2 >= 10:\n                options.append(((0, 0, W, H - hc - 2), (0, H - hc - 2, W), (0, H - hc, W, hc)))\n            wc = min(max(44, int(W * 0.40)), W - 24)\n            if wc >= 30:\n                wa = W - wc - 1\n                options.append(((0, 0, wa, H), (wa + 1, 0, wc), (wa + 1, 2, wc, H - 2)))\n        if not options:\n            options.append(((0, 0, W, H - 1), (0, H - 1, W), None))\n        self.art, self.status, self.code = max(\n            options, key=lambda o: np.prod(fit(o[0][2], max(1, o[0][3] - 4))))\n        ax, ay, aw, ah = self.art\n        vw, vh = fit(aw, max(1, ah - 4))\n        self.video = (ax + (aw - vw) // 2, ay + 1 + (max(1, ah - 4) - vh) // 2, vw, vh)\n\n\n# ── video, sound and the terminal ───────────────────────────────────────────\nclass Video:\n    def __init__(self, ff, path):\n        if not os.path.isfile(path):\n            sys.exit(f\"no such video: {path}\")\n        info = subprocess.run([ff, \"-hide_banner\", \"-nostdin\", \"-i\", path],\n                              capture_output=True, text=True, errors=\"replace\").stderr\n        dur = re.search(r\"Duration:\\s*(\\d+):(\\d+):([\\d.]+)\", info)\n        size = re.search(r\"Video:.*?,\\s*(\\d{2,5})x(\\d{2,5})\", info)\n        if not (dur and size):\n            sys.exit(f\"ffmpeg could not read {path}\")\n        h, m, s = dur.groups()\n        self.duration = int(h) * 3600 + int(m) * 60 + float(s)\n        w, hh = int(size.group(1)), int(size.group(2))\n        rot = re.search(r\"rotation of (-?[\\d.]+)\", info)\n        if rot and abs(round(float(rot.group(1)))) % 180 == 90:\n            w, hh = hh, w\n        self.aspect = w / hh\n        self.audio = re.search(r\"Stream #.*Audio:\", info) is not None\n\n\nclass Frames:\n    \"\"\"ffmpeg decodes and scales; a thread hands the frames over as numpy arrays.\"\"\"\n\n    def __init__(self, ff, path, size, fps, start):\n        self.w, self.h = size\n        self.first = round(start * fps)\n        vf = f\"fps={fps},crop=iw*{CROP}:ih*{CROP},scale={self.w}:{self.h}:flags=area,format=gbrp\"\n        self.proc = subprocess.Popen(\n            [ff, \"-nostdin\", \"-loglevel\", \"error\", \"-ss\", f\"{start:.3f}\", \"-i\", path,\n             \"-an\", \"-vf\", vf, \"-f\", \"rawvideo\", \"-\"],\n            stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)\n        self.q, self.stop, self.ended = queue.Queue(maxsize=4), False, False\n        self.cur, self.cur_i = None, self.first - 1\n        threading.Thread(target=self._pump, daemon=True).start()\n\n    def _put(self, item):\n        while not self.stop:\n            try:\n                return self.q.put(item, timeout=0.1)\n            except queue.Full:\n                pass\n\n    def _pump(self):\n        n, i = 3 * self.w * self.h, self.first\n        while not self.stop:\n            buf = self.proc.stdout.read(n)\n            if len(buf) < n:\n                break\n            self._put((i, np.frombuffer(buf, np.uint8).reshape(3, self.h, self.w)))\n            i += 1\n        self._put(None)\n\n    def get(self, idx):\n        \"\"\"the newest frame at or before idx (late frames are skipped). None = the end.\"\"\"\n        while (self.cur is None or self.cur_i < idx) and not self.ended:\n            try:                                      # ffmpeg can be slow to wake (virus scans...):\n                item = self.q.get(timeout=0.25)       # only its closing the pipe means \"the end\"\n            except queue.Empty:\n                continue\n            if item is None:\n                self.ended = True\n            else:\n                self.cur_i, self.cur = item\n        return None if self.ended and self.cur_i < idx else self.cur\n\n    def close(self):\n        self.stop = True\n        self.proc.kill()\n        self.proc.wait()\n\n\nclass Sound:\n    \"\"\"pulls the soundtrack out to a wav and plays it alongside the picture.\"\"\"\n\n    def __init__(self, ff, path, start):\n        fd, self.wav = tempfile.mkstemp(prefix=\"art_\", suffix=\".wav\")\n        os.close(fd)\n        self.extract = subprocess.Popen(                 # runs in the background while we set up\n            [ff, \"-nostdin\", \"-loglevel\", \"error\", \"-y\", \"-ss\", f\"{start:.3f}\", \"-i\", path,\n             \"-vn\", \"-ac\", \"2\", \"-ar\", \"44100\", \"-c:a\", \"pcm_s16le\", self.wav],\n            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n        self.ok, self.proc = None, None\n\n    def ready(self):\n        if self.ok is None:\n            self.ok = self.extract.wait() == 0 and os.path.getsize(self.wav) > 1024\n        return self.ok\n\n    def play(self):\n        if not self.ready():\n            return\n        if os.name == \"nt\":\n            import winsound\n            winsound.PlaySound(self.wav, winsound.SND_FILENAME | winsound.SND_ASYNC | winsound.SND_NODEFAULT)\n            return\n        for cmd in ([\"afplay\"], [\"paplay\"], [\"aplay\", \"-q\"], [\"ffplay\", \"-nodisp\", \"-autoexit\", \"-loglevel\", \"quiet\"]):\n            if shutil.which(cmd[0]):\n                self.proc = subprocess.Popen(cmd + [self.wav], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n                return\n\n    def stop(self):\n        if os.name == \"nt\" and self.ok:\n            import winsound\n            winsound.PlaySound(None, 0)\n        if self.proc:\n            self.proc.terminate()\n            self.proc = None\n\n    def close(self):\n        if self.extract.poll() is None:\n            self.extract.kill()\n            self.extract.wait()\n        self.stop()\n        try:\n            os.remove(self.wav)\n        except OSError:\n            pass\n\n\nclass Terminal:\n    \"\"\"raw terminal i/o. a writer thread feeds the console while the next frame is drawn.\"\"\"\n\n    def __init__(self):\n        self.saved, self.dead = None, False\n        self.q = queue.Queue(maxsize=1)\n        threading.Thread(target=self._writer, daemon=True).start()\n\n    def _writer(self):\n        out = sys.stdout.buffer\n        while True:\n            data = self.q.get()\n            try:\n                if data is not None and not self.dead:\n                    out.write(data)\n                    out.flush()\n            except (OSError, ValueError):             # the window went away\n                self.dead = True\n            finally:\n                self.q.task_done()\n\n    def write(self, s):\n        data = s.encode(\"utf-8\")\n        while not self.dead:                          # short waits keep Ctrl+C working\n            try:\n                return self.q.put(data, timeout=0.1)\n            except queue.Full:\n                pass\n\n    def drain(self, patience=3.0):\n        end = time.perf_counter() + patience\n        while self.q.unfinished_tasks and not self.dead and time.perf_counter() < end:\n            time.sleep(0.005)\n\n    def open(self):\n        if os.name == \"nt\":\n            import ctypes\n            ctypes.windll.winmm.timeBeginPeriod(1)      # 1 ms sleeps, not 15.6 ms ticks\n            k32 = ctypes.windll.kernel32\n            out, mode = k32.GetStdHandle(-11), ctypes.c_uint32()\n            if k32.GetConsoleMode(out, ctypes.byref(mode)):\n                self.saved = (out, mode.value, k32.GetConsoleOutputCP())\n                k32.SetConsoleMode(out, mode.value | 0x0001 | 0x0004)   # processed + VT sequences\n                k32.SetConsoleOutputCP(65001)\n        elif sys.stdin.isatty():\n            import termios\n            import tty\n            self.saved = termios.tcgetattr(sys.stdin.fileno())\n            tty.setcbreak(sys.stdin.fileno())\n        self.write(\"\\x1b[?1049h\\x1b[?25l\\x1b[?7l\\x1b[0m\\x1b[2J\")\n\n    def close(self):\n        self.write(\"\\x1b[0m\\x1b[?7h\\x1b[?25h\\x1b[?1049l\")\n        self.drain()\n        if os.name == \"nt\":\n            import ctypes\n            ctypes.windll.winmm.timeEndPeriod(1)\n            if self.saved:\n                out, mode, cp = self.saved\n                ctypes.windll.kernel32.SetConsoleMode(out, mode)\n                ctypes.windll.kernel32.SetConsoleOutputCP(cp)\n        elif self.saved is not None:\n            import termios\n            termios.tcsetattr(sys.stdin.fileno(), termios.TCSADRAIN, self.saved)\n\n    @staticmethod\n    def colours(choice):\n        \"\"\"24-bit colour everywhere it's fast. the classic Windows console chokes on it,\n        and macOS Terminal.app can't show it, so those two get the 256-colour palette.\"\"\"\n        if choice != \"auto\":\n            return int(choice)\n        env = os.environ\n        modern = env.get(\"WT_SESSION\") or env.get(\"TERM_PROGRAM\") or env.get(\"COLORTERM\") in (\"truecolor\", \"24bit\")\n        if (os.name == \"nt\" and not modern) or env.get(\"TERM_PROGRAM\") == \"Apple_Terminal\":\n            return 256\n        return 24\n\n    @staticmethod\n    def size():\n        w, h = shutil.get_terminal_size((100, 40))\n        return max(20, w), max(10, h)\n\n    def key(self):\n        \"\"\"the key pressed since last time, if any. arrows and F-keys are swallowed whole.\"\"\"\n        if os.name == \"nt\":\n            import msvcrt\n            if not msvcrt.kbhit():\n                return \"\"\n            ch = msvcrt.getwch()\n            if ch in (\"\\x00\", \"\\xe0\"):                # an arrow / F-key: a prefix plus a code letter\n                msvcrt.getwch()\n                return \"\"\n            return ch\n        if self.saved is not None:\n            import select\n            if select.select([sys.stdin], [], [], 0)[0]:\n                ch = os.read(sys.stdin.fileno(), 1).decode(errors=\"ignore\")\n                if ch == \"\\x1b\" and select.select([sys.stdin], [], [], 0.02)[0]:\n                    os.read(sys.stdin.fileno(), 16)  # the tail of an arrow / F-key sequence\n                    return \"\"\n                return ch\n        return \"\"\n\n\ndef find_ffmpeg():\n    exe = shutil.which(\"ffmpeg\")\n    if exe:\n        return exe\n    import glob\n    import importlib.util\n    spec = importlib.util.find_spec(\"imageio_ffmpeg\")    # its bundled binary, found without importing it\n    if spec and spec.origin:\n        for hit in glob.glob(os.path.join(os.path.dirname(spec.origin), \"binaries\", \"ffmpeg*\")):\n            if os.path.isfile(hit) and not hit.endswith((\".md\", \".py\", \".txt\")):\n                return hit\n    try:\n        import imageio_ffmpeg\n        return imageio_ffmpeg.get_ffmpeg_exe()\n    except Exception:\n        sys.exit(\"ffmpeg not found. install it with:   pip install imageio-ffmpeg\")\n\n\n# ── putting it together ─────────────────────────────────────────────────────\ndef compose(scr, lay, full, look, ink, stars, code, clock, t, info):\n    \"\"\"draw one whole frame (art, stars, HUD, status line, code) into the screen buffer.\"\"\"\n    scr.clear()\n    vx, vy, vw, vh = lay.video\n    half = np.add(full[:, 0::2, 0::2], full[:, 1::2, 0::2], dtype=np.uint16)\n    half += full[:, 0::2, 1::2]\n    half += full[:, 1::2, 1::2]\n    cells = to_cells(half, SX // 2, SY // 2, 1 / (4 * 255))       # 2x2 average: a 2x4 sample per cell\n    if look == \"ascii\":\n        glyph, fg = ink(cells, full)\n        scr.ch[vy: vy + vh, vx: vx + vw] = CHARS[glyph].reshape(vh, vw)\n        scr.fg[vy: vy + vh, vx: vx + vw] = fg.reshape(vh, vw)\n        drawn = int(np.count_nonzero(glyph))\n    else:\n        top, bottom = pixels(cells)\n        scr.ch[vy: vy + vh, vx: vx + vw] = \"▀\"\n        scr.fg[vy: vy + vh, vx: vx + vw] = top.reshape(vh, vw)\n        scr.bg[vy: vy + vh, vx: vx + vw] = bottom.reshape(vh, vw)\n        drawn = vw * vh\n    sign = info.get(\"sign\")\n    if sign and t >= sign.start:                      # the closing card: your @, big enough to read\n        sign.draw(scr, lay.video, t - sign.start)\n\n    ax, ay, aw, ah = lay.art\n    stars.draw(scr, ax, ay, aw, ah, clock)\n    stamp = f\" t {t:05.2f}s\"\n    scr.put(ax + aw - len(stamp) - 2, ay, \"■\", C_PINK)\n    scr.put(ax + aw - len(stamp) - 1, ay, stamp, C_PINK)\n    lines = (f\"{info['tag']} · {time.localtime().tm_year}\",\n             f\"frame {info['frame']:04d}/{info['frames']:04d}   played {100 * info['frame'] / info['frames']:5.1f}%\",\n             f\"glyphs {drawn:,}   look {look}\")\n    for i, text in enumerate(lines):\n        scr.put(ax + 1, ay + ah - 3 + i, text, C_HUD)\n\n    sx, sy, sw = lay.status\n    scr.put(sx, sy, f\"$ py {info['script']}\", C_STATUS)\n    right = f\"running · {info['fps']:.0f} fps\"\n    scr.put(sx + sw - len(right) - 1, sy, right, C_HUD)\n    if lay.code:\n        x, y, w, h = lay.code\n        scr.put(x, y - 1, \"─\" * w, C_RULE)\n        code.draw(scr, x, y, w, h, clock)\n\n\ndef play(args, ff, video, sound, term):\n    fps = args.fps\n    total = max(1, int((video.duration - args.start) * fps) + round(args.start * fps))\n    sign_path = os.path.join(HERE, \"signature.npz\")\n    sign = Signature(sign_path) if (os.path.isfile(sign_path) and not args.no_sign\n                                    and os.path.basename(args.video).startswith(\"feelings\")) else None\n    info = {\"tag\": args.tag or (sign.name if sign else os.path.splitext(os.path.basename(args.video))[0]),\n            \"script\": os.path.basename(sys.argv[0]) or \"art.py\", \"frames\": total, \"fps\": fps, \"frame\": 0,\n            \"sign\": sign}\n    look, show_code, colours = args.look, not args.no_code, Terminal.colours(args.colours)\n    ink, stars, code = Ink(), Stars(), Code(os.path.abspath(__file__), args.cps)\n    frames = scr = lay = size = clock0 = last = None\n    shown = 0\n    try:\n        while not term.dead:\n            key = term.key().lower()\n            if key in (\"q\", \"\\x1b\", \"\\x03\"):\n                break\n            if key == \"m\":\n                look = \"pixels\" if look == \"ascii\" else \"ascii\"\n            if key == \"c\":\n                show_code, size = not show_code, None\n\n            if term.size() != size:                   # first frame, or the window changed size\n                size = term.size()\n                scr, lay = Screen(*size, colours), Layout(*size, video.aspect, show_code, args.cell)\n                term.write(\"\\x1b[0m\\x1b[2J\")\n                now_t = args.start if clock0 is None else args.start + time.perf_counter() - clock0 - args.sync\n                if frames:\n                    frames.close()\n                frames = Frames(ff, args.video, (lay.video[2] * SX, lay.video[3] * SY), fps, max(args.start, now_t))\n\n            if clock0 is None:                        # wait for ffmpeg, then start the clock\n                note = \"warming up the projector ...\"\n                term.write(f\"\\x1b[{size[1] // 2};{max(1, (size[0] - len(note)) // 2)}H\\x1b[38;2;110;110;122m{note}\")\n                frames.get(frames.first)\n                if sound:\n                    sound.play()\n                clock0 = time.perf_counter()\n\n            clock = time.perf_counter() - clock0\n            index = max(frames.first, int((args.start + clock - args.sync) * fps))\n            frame = frames.get(index) if index < total else None\n            if frame is None:                         # the end: stop, or go round again\n                if not args.loop:\n                    break\n                frames.close()\n                frames = Frames(ff, args.video, (lay.video[2] * SX, lay.video[3] * SY), fps, args.start)\n                frames.get(frames.first)\n                if sound:\n                    sound.stop()\n                    sound.play()\n                clock0 = time.perf_counter()\n                continue\n\n            now = time.perf_counter()\n            if last is not None:\n                info[\"fps\"] += (1 / max(now - last, 1e-3) - info[\"fps\"]) * 0.1\n            last = now\n            info[\"frame\"] = index\n            compose(scr, lay, frame, look, ink, stars, code, clock, index / fps, info)\n            term.write(scr.flush())\n            shown += 1\n            wait = clock0 + (index + 1) / fps - args.start + args.sync - time.perf_counter()\n            if wait > 0:\n                time.sleep(wait)\n    finally:\n        if frames:\n            frames.close()\n    return shown, (time.perf_counter() - clock0) if clock0 else 0.0, colours\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=\"play a video as living ASCII art in the terminal\")\n    ap.add_argument(\"video\", nargs=\"?\", default=EDIT)\n    ap.add_argument(\"--no-sign\", action=\"store_true\", help=\"don't draw your @ (signature.npz) over the closing card\")\n    ap.add_argument(\"--look\", choices=(\"ascii\", \"pixels\"), default=\"ascii\",\n                    help=\"ascii = glyphs on black like the rose, pixels = sharp colour blocks\")\n    ap.add_argument(\"--no-code\", action=\"store_true\", help=\"hide the code pane\")\n    ap.add_argument(\"--mute\", action=\"store_true\", help=\"no sound\")\n    ap.add_argument(\"--loop\", action=\"store_true\", help=\"play forever\")\n    ap.add_argument(\"--start\", type=float, default=0.0, help=\"start this many seconds in\")\n    ap.add_argument(\"--fps\", type=float, default=30.0)\n    ap.add_argument(\"--tag\", help='the credit line in the corner, e.g. \"@yourname\"')\n    ap.add_argument(\"--cps\", type=float, default=170.0, help=\"typing speed of the code pane\")\n    ap.add_argument(\"--cell\", type=float, default=2.0, help=\"height / width of one terminal cell\")\n    ap.add_argument(\"--sync\", type=float, default=0.0, help=\"delay the picture (s) if sound runs late\")\n    ap.add_argument(\"--colours\", \"--colors\", choices=(\"auto\", \"24\", \"256\"), default=\"auto\",\n                    help=\"24-bit colour or the 256 palette (auto picks 256 in the old Windows console)\")\n    args = ap.parse_args()\n\n    ff = find_ffmpeg()\n    video = Video(ff, args.video)\n    print(f\"loading {os.path.basename(args.video)} ...\", flush=True)\n    sound = Sound(ff, args.video, args.start) if video.audio and not args.mute else None\n    term = Terminal()\n    shown, secs, colours = 0, 0.0, 24\n    try:\n        term.open()\n        shown, secs, colours = play(args, ff, video, sound, term)\n    except KeyboardInterrupt:\n        pass\n    finally:\n        term.close()\n        if sound:\n            sound.close()\n    if secs:\n        print(f\"drew {shown} frames in {secs:.1f}s  ({shown / secs:.1f} fps, {colours}-bit colour)\"\n              if colours == 24 else f\"drew {shown} frames in {secs:.1f}s  ({shown / secs:.1f} fps, 256 colours)\")\n        if os.name == \"nt\" and colours == 256:\n            print(\"tip: Windows Terminal or the VS Code terminal show full colour at a smoother frame rate\")\n\n\nif __name__ == \"__main__\":\n    main()\n", "flowers": "#!/usr/bin/env python3\n\"\"\"\nflowers.py - a little garden grows in your terminal under the stars, then spins,\nto \"Reflections\" by The Neighbourhood (0:38-1:15, looping: reflections.m4a).\n\n    python flowers.py\n    python flowers.py --speed 0.6       spin faster from the start\n    python flowers.py --mute            no music\n\nkeys:   up / down   (or + / -)      spin faster / slower\n        right / left                push the spin that way (through zero and back)\n        space  pause     r  reverse     g  grow it all again\n        m  switch look (hd pixels / letters)\n        c  show / hide the code         q  quit\n\nneeds numpy, plus art.py next to it (the screen + terminal plumbing lives there)\n\"\"\"\n\nfrom __future__ import annotations\n\nimport argparse\nimport math\nimport os\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nimport time\n\nimport numpy as np\n\nfrom art import (CHARS, C_HUD, C_PINK, C_RULE, C_STATUS, SHAPE, Code, Layout, Screen, Sound, Stars, Terminal,\n                 find_ffmpeg, pack)\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nSONG = os.path.join(HERE, \"reflections.m4a\")   # 0:38-1:15 of the song; its end melts into its start, so it loops\nCREDIT = \"reflections · the neighbourhood\"\nLEAD = 0.39             # the music starts this much before the garden, so the spin begins on the big beat\nTAU = 2 * math.pi\nTILT = 0.26             # the camera looks down on the garden a little (radians)\nAIM_Y = 0.78            # the height the camera aims at\nDIST = 4.2              # camera distance, for a touch of perspective\nSPAN_X, SPAN_Y = 2.0, 1.75   # how much of the world has to fit on screen (wide, tall)\nGROW, OPEN = 4.0, 3.2   # seconds for a stem to grow, and for its flower to open\nMAX_SPIN = 3.0          # turns per second, either way\n\n\n# ── the garden ──────────────────────────────────────────────────────────────\n# every flower: its stem runs from base to top (x, height, z), it starts growing\n# at `start` seconds, its head is `size` times life size and leans out by `tilt`\n# degrees, and its leaves sit at (height up the stem, turn in degrees, length)\nGARDEN = [\n    dict(kind=\"lavender\", base=(0.04, 0, -0.05), top=(0.42, 1.05, -0.40), start=0.5, size=1.4, tilt=10,\n         leaves=[(0.22, 40, 0.20), (0.36, 220, 0.18)]),\n    dict(kind=\"tulip\", base=(-0.06, 0, 0.03), top=(-0.55, 1.02, 0.12), start=0.9, size=1.5, tilt=15,\n         leaves=[(0.04, 150, 0.56), (0.09, 330, 0.50)]),\n    dict(kind=\"daisy\", base=(0.06, 0, 0.04), top=(0.50, 0.88, 0.32), start=1.3, size=1.6, tilt=50,\n         leaves=[(0.30, 250, 0.26), (0.48, 80, 0.24)]),\n    dict(kind=\"lily\", base=(-0.03, 0, -0.06), top=(-0.25, 1.15, -0.50), start=1.7, size=1.45, tilt=40,\n         leaves=[(0.18, 120, 0.38), (0.40, 300, 0.34)]),\n    dict(kind=\"rose\", base=(0.0, 0, 0.0), top=(0.0, 1.30, -0.04), start=2.1, size=1.7, tilt=25,\n         leaves=[(0.30, 200, 0.34), (0.50, 20, 0.30)]),\n]\n\n\n# ── the art ─────────────────────────────────────────────────────────────────\n# flowers are real 3d surfaces: petals and leaves are bent sheets, stems are\n# curves. each frame they are spun, lit, squashed onto the character grid,\n# and the nearest point in every cell decides its glyph: bright faces get\n# dense letters, outlines get / \\ ( ) _ - that follow the edge.\ndef smooth(x):\n    x = np.clip(x, 0.0, 1.0)\n    return x * x * (3 - 2 * x)\n\n\ndef ease_out(x):\n    return 1 - (1 - np.clip(x, 0.0, 1.0)) ** 3\n\n\ndef lerp(a, b, t):\n    return a + (b - a) * t\n\n\ndef unit(v):\n    return v / np.maximum(np.linalg.norm(v, axis=-1, keepdims=True), 1e-9)\n\n\ndef rot_y(a):\n    c, s = math.cos(a), math.sin(a)\n    return np.array([[c, 0, s], [0, 1, 0], [-s, 0, c]])\n\n\ndef rot_x(a):\n    c, s = math.cos(a), math.sin(a)\n    return np.array([[1, 0, 0], [0, c, -s], [0, s, c]])\n\n\ndef frame_for(axis):\n    \"\"\"three unit rows (x, y, z) of a frame whose y points along `axis`.\"\"\"\n    a = unit(np.asarray(axis, float))\n    ref = np.array([1.0, 0, 0]) if abs(a[0]) < 0.9 else np.array([0, 0, 1.0])\n    x = unit(ref - a * (ref @ a))\n    return np.stack([x, a, np.cross(x, a)])\n\n\ndef rgb01(c):\n    return np.asarray(c, float) / 255\n\n\nclass Bits:\n    \"\"\"a pile of points with everything the renderer needs to know about each one.\n    `part` numbers the separate pieces (each petal, each leaf) so outlines know where one ends.\"\"\"\n\n    def __init__(self, P, N, C, T=None, part=None, thin=False, shine=0.0):\n        P = np.asarray(P, float)\n        n = P.size // 3\n        self.P = P.reshape(n, 3)\n        self.N = np.broadcast_to(N, P.shape).reshape(n, 3)\n        self.C = np.broadcast_to(C, P.shape).reshape(n, 3)\n        self.T = np.zeros((n, 3)) if T is None else np.broadcast_to(T, P.shape).reshape(n, 3)\n        self.part = np.zeros(n, np.int64) if part is None else np.broadcast_to(part, P.shape[:-1]).reshape(n)\n        self.thin = np.full(n, thin)\n        self.shine = np.full(n, float(shine))\n\n\nclass Stem:\n    \"\"\"a gentle curve from the ground to the flower (a quadratic bezier).\"\"\"\n\n    def __init__(self, base, top, radius):\n        self.B, self.E, self.r = np.array(base, float), np.array(top, float), radius\n        self.K = self.B + (self.E - self.B) * np.array([0.15, 0.62, 0.15])   # rise first, then lean\n        self.length = np.linalg.norm(self.E - self.B) * 1.08\n\n    def at(self, s):\n        s = np.asarray(s, float)[:, None]\n        p = (1 - s) ** 2 * self.B + 2 * (1 - s) * s * self.K + s * s * self.E\n        d = 2 * (1 - s) * (self.K - self.B) + 2 * s * (self.E - self.K)\n        return p, unit(d)\n\n    def bits(self, g, res, colour):\n        n = int(np.clip(self.length * g * res * 1.2, 3, 400))\n        s = np.linspace(0, g, n)\n        c, t = self.at(s)\n        n1 = unit(np.cross(t, [0, 0, 1.0]))\n        n2 = np.cross(t, n1)\n        a = np.linspace(0, TAU, 6, endpoint=False)[None, :, None]\n        ring = np.cos(a) * n1[:, None] + np.sin(a) * n2[:, None]\n        P = c[:, None] + self.r * (1 - 0.35 * s)[:, None, None] * ring\n        shade = lerp(rgb01((36, 110, 42)), rgb01((84, 165, 64)), s[:, None, None] / max(g, 1e-6))\n        return Bits(P, ring, np.broadcast_to(shade * colour, P.shape), T=np.broadcast_to(t[:, None], P.shape), thin=True)\n\n\ndef leaf(origin, turn, rise, length, width, droop, f, res):\n    \"\"\"a leaf unfolding from the stem: f = 0 is tucked against it, 1 is wide open.\"\"\"\n    elev = lerp(math.radians(84), math.radians(rise), f)\n    h = np.array([math.cos(turn), 0, math.sin(turn)])\n    d = unit(h * math.cos(elev) + np.array([0, 1.0, 0]) * math.sin(elev))\n    w = unit(np.cross([0, 1.0, 0], d))\n    n = np.cross(d, w)\n    L, W = length * (0.12 + 0.88 * f), width * f ** 0.7 + 1e-4\n    nu, nv = int(np.clip(L * res * 1.1, 4, 80)), int(np.clip(2 * W * res * 1.1, 3, 30))\n    u = np.linspace(0, 1, nu)[:, None]\n    v = np.linspace(-1, 1, nv)[None, :]\n    lat = v * W * np.sin(np.pi * u ** 0.8) ** 0.9 * (1 - 0.2 * u)\n    lift = 0.9 * lat * lat / W - droop * (u * L) ** 2\n    P = origin + d * (u * L)[..., None] + w * lat[..., None] + n * lift[..., None]\n    du, dv = np.gradient(P, axis=0), np.gradient(P, axis=1)\n    rib = np.clip(1 - np.abs(v) * 5, 0, 1)[..., None] * 0.12\n    side = (np.clip(np.cos((u - 0.45 * np.abs(v)) * TAU * 6), 0, 1) ** 8 * (np.abs(v) < 0.88) * 0.1)[..., None]\n    C = lerp(rgb01((30, 98, 38)), rgb01((96, 178, 72)), u[..., None]) + rib + side   # midrib and side veins\n    return Bits(P, unit(np.cross(du, dv)), C, shine=0.12)\n\n\nclass Petals:\n    \"\"\"a ring or spiral of petals, one number per petal for each property.\"\"\"\n\n    def __init__(self, phi, length, width, r0, h0, closed, opened, bend0, bend1, cup, shape,\n                 base, tip, shine, fade=0.6, stripe=None, spots=None, veins=(0, 0.0)):\n        k = np.shape(phi)\n        f = lambda x: np.broadcast_to(np.asarray(x, float), k).copy()   # noqa: E731\n        self.phi, self.L, self.W, self.r0, self.h0 = f(phi), f(length), f(width), f(r0), f(h0)\n        self.closed, self.opened = np.radians(f(closed)), np.radians(f(opened))\n        self.bend0, self.bend1, self.cup = f(bend0), f(bend1), f(cup)\n        self.shape, self.base, self.tip, self.shine, self.fade = shape, rgb01(base), rgb01(tip), shine, fade\n        self.stripe, self.spots, self.veins = stripe, spots, veins\n\n    def bits(self, b, res):\n        \"\"\"b = how open the flower is, 0 bud .. 1 full bloom. points are in head space (axis = +y).\"\"\"\n        L = self.L * lerp(0.55, 1.0, b)\n        nu = int(np.clip(L.max() * res * 1.05, 5, 60))\n        nv = int(np.clip(2 * self.W.max() * res * 1.05, 4, 44))\n        u = np.linspace(0, 1, nu)[None, :, None]\n        v = np.linspace(-1, 1, nv)[None, None, :]\n        col = lambda x: x[:, None, None]                                  # noqa: E731\n        # the spine of each petal: it leaves the centre at an angle and keeps bending\n        ang = col(lerp(self.closed, self.opened, b)) + col(lerp(self.bend0, self.bend1, b)) * u * col(L)\n        s, c = np.sin(ang), np.cos(ang)\n        rho = col(self.r0) + col(L) * (np.cumsum(s, 1) - s[:, :1]) / (nu - 1)\n        hgt = col(self.h0) + col(L) * (np.cumsum(c, 1) - c[:, :1]) / (nu - 1)\n        if self.shape == \"round\":\n            prof = u ** 0.45 * np.sqrt(np.clip(1 - u ** 5, 0, 1))\n        elif self.shape == \"strap\":\n            prof = np.sqrt(np.clip(u * 6, 0, 1) * np.clip(1 - u ** 8, 0, 1))\n        else:\n            prof = np.sin(np.pi * u ** 0.7) ** 1.1\n        lat = v * col(self.W) * prof                                      # across the petal\n        out = col(self.cup) * lat * lat / col(self.W)                      # the cup of the petal\n        cp, sp = np.cos(self.phi)[:, None, None], np.sin(self.phi)[:, None, None]\n        r = rho - out * c\n        P = np.stack(np.broadcast_arrays(r * cp - lat * sp, hgt + out * s, r * sp + lat * cp), -1)\n        du, dv = np.gradient(P, axis=1), np.gradient(P, axis=2)\n        C = lerp(self.base, self.tip, (u ** self.fade)[..., None]) * (1 - 0.4 * np.abs(v) ** 6)[..., None]\n        count, depth = self.veins                                       # fine veins running up the petal\n        C = C * (1 - depth * (0.5 + 0.5 * np.cos(v * count * np.pi)) ** 6 * (0.3 + 0.7 * u))[..., None]\n        C = np.broadcast_to(C, P.shape).copy()                          # darker rims keep petals apart\n        if self.stripe is not None:                                       # a lily's painted stripe\n            w = (np.exp(-(v / 0.22) ** 2) * (1 - u) ** 0.5 * 0.8)[..., None]\n            C = lerp(C, rgb01(self.stripe), np.broadcast_to(w, C.shape))\n        if self.spots is not None:                                        # and its freckles\n            k = np.arange(len(self.phi))[:, None, None]\n            spot = (np.sin(u * 91 + v * 37 + k * 13) * np.sin(u * 53 - v * 71) > 0.82) & (u < 0.55) & (np.abs(v) < 0.65)\n            C[spot] = rgb01(self.spots)\n        petal = np.arange(len(self.phi))[:, None, None]                   # every petal is its own part\n        return Bits(P, unit(np.cross(du, dv)), C, part=np.broadcast_to(petal, P.shape[:3]), shine=self.shine)\n\n\ndef head(kind):\n    \"\"\"the petal sets that make each kind of flower.\"\"\"\n    if kind == \"rose\":                                # a golden-angle spiral, tight inside, loose outside\n        sets = []\n        for k in (np.arange(0, 10), np.arange(10, 24)):\n            q = k / 23\n            sets.append(Petals(np.radians(k * 137.508), 0.09 + 0.17 * q, 0.05 + 0.09 * q, 0.004 + 0.022 * q,\n                               -0.035 * q, 4 + 14 * q, 8 + 60 * q ** 1.4, -3.0 + q,\n                               -3.2 * (1 - q) ** 2 + 3.6 * q * q, 0.75 - 0.4 * q, \"round\",\n                               (110, 6, 32), (238, 48, 98), 0.25, veins=(5, 0.07)))\n        return sets + [Petals(np.radians(np.arange(5) * 72 + 18), 0.075, 0.026, 0.01, -0.03, 15, 125, 0, 1.5,\n                              0.3, \"point\", (40, 110, 40), (82, 160, 62), 0.05)]       # the green sepals\n    if kind == \"tulip\":\n        phi = np.radians([0, 120, 240, 60, 180, 300])\n        inner = np.array([1, 1, 1, 0, 0, 0])\n        return [Petals(phi, 0.31 - 0.02 * inner, 0.155 - 0.015 * inner, 0.018 - 0.012 * inner, 0,\n                       5, 30 - 10 * inner, -1.4, -0.5, 1.15, \"round\", (255, 226, 70), (255, 128, 18), 0.4, fade=0.5,\n                       veins=(11, 0.09))]\n    if kind == \"daisy\":\n        k = np.arange(21)\n        return [Petals(np.radians(k * 360 / 21 + 4 * np.sin(k * 2.3)), 0.23 + 0.02 * np.sin(k * 1.7), 0.032,\n                       0.05, 0.012, 12, 82 + 5 * np.sin(k * 3.1), -1.2, 0.5, 0.15, \"strap\",\n                       (255, 236, 170), (255, 250, 255), 0.12, veins=(2, 0.16))]\n    if kind == \"lily\":\n        return [Petals(np.radians(np.arange(6) * 60 + 30), 0.33, 0.072, 0.012, 0, 6, 46, -0.8, 4.4, 0.45,\n                       \"point\", (255, 250, 246), (255, 140, 196), 0.3, stripe=(214, 32, 122), spots=(140, 16, 72),\n                       veins=(5, 0.1))]\n    return []\n\n\ndef disk(b, res):\n    \"\"\"the golden middle of a daisy: a low dome.\"\"\"\n    n = int(np.clip(0.06 * res * 3, 6, 40))\n    a = np.linspace(0, 1, n)[:, None]\n    th = np.linspace(0, TAU, 2 * n, endpoint=False)[None, :]\n    R, H = 0.052, 0.03 * (0.4 + 0.6 * b)\n    slope = 2 * H * a / R\n    P = np.stack(np.broadcast_arrays(R * a * np.cos(th), 0.012 + H * (1 - a * a), R * a * np.sin(th)), -1)\n    N = unit(np.stack(np.broadcast_arrays(slope * np.cos(th), np.ones_like(a), slope * np.sin(th)), -1))\n    grain = (0.85 + 0.15 * np.sin(a * 40) * np.sin(th * 9))[..., None]\n    C = lerp(rgb01((214, 104, 20)), rgb01((255, 206, 42)), a[..., None]) * grain\n    return Bits(P, N, np.broadcast_to(C, P.shape), shine=0.2)\n\n\ndef stamens(b, res):\n    \"\"\"six lily stamens: thin threads with a dusty anther on each.\"\"\"\n    phi = np.radians(np.arange(6) * 60)[:, None]\n    n = int(np.clip(0.22 * res * 1.5, 6, 40))\n    s = np.linspace(0, 1, n)[None, :]\n    ang = math.radians(lerp(4, 28, b)) + 0.6 * s\n    rho = 0.21 * np.cumsum(np.sin(ang), 1) / n\n    y = 0.01 + 0.21 * np.cumsum(np.cos(ang), 1) / n * lerp(0.5, 1, b)\n    P = np.stack(np.broadcast_arrays(rho * np.cos(phi), y, rho * np.sin(phi)), -1)\n    T = unit(np.gradient(P, axis=1))\n    thread = Bits(P, T, rgb01((232, 236, 200)), T=T, thin=True)\n    tip = P[:, -1]\n    o = np.array([[0.01, 0, 0], [-0.01, 0, 0], [0, 0.008, 0], [0, 0, 0.01], [0, 0, -0.01], [0, -0.006, 0]])\n    A = tip[:, None] + o[None]\n    dust = Bits(A, unit(o)[None].repeat(6, 0), rgb01((200, 86, 26)), part=np.arange(6)[:, None], shine=0.1)\n    return [thread, dust]\n\n\ndef florets(stem, g, size):\n    \"\"\"lavender: little violet buds spiralling up the top of the stem.\"\"\"\n    s = np.linspace(0.62, 1.0, 22)\n    pop = smooth((g - s) / 0.08)\n    s, pop = s[pop > 0], pop[pop > 0]\n    if not len(s):\n        return []\n    c, t = stem.at(s)\n    k = np.arange(len(s)) * 2.4\n    side = unit(np.cross(t, [0, 0, 1.0]))\n    side = side * np.cos(k)[:, None] + np.cross(t, side) * np.sin(k)[:, None]\n    centre = c + side * 0.028 * size\n    r = (0.026 - 0.012 * (s - 0.62) / 0.38) * pop * size\n    la = np.linspace(0, np.pi, 6)[None, :, None]\n    lo = np.linspace(0, TAU, 10, endpoint=False)[None, None, :]\n    ball = np.stack(np.broadcast_arrays(np.sin(la) * np.cos(lo), np.cos(la), np.sin(la) * np.sin(lo)), -1)\n    P = centre[:, None, None] + r[:, None, None, None] * ball\n    C = lerp(rgb01((196, 146, 255)), rgb01((118, 72, 222)), ((s - 0.62) / 0.38)[:, None, None, None])\n    bud = np.arange(len(s))[:, None, None]\n    return [Bits(P, np.broadcast_to(ball, P.shape), np.broadcast_to(C, P.shape), part=bud, shine=0.15)]\n\n\ndef grass(f, res):\n    \"\"\"a tuft of grass blades around the base, drawn as thin strokes.\"\"\"\n    rng = np.random.default_rng(11)\n    n = 34\n    a, r = rng.uniform(0, TAU, n), rng.uniform(0.02, 0.26, n)\n    h, lean = rng.uniform(0.10, 0.30, n) * f, rng.uniform(0.25, 0.75, n)\n    m = int(np.clip(0.3 * res * 1.5, 4, 24))\n    s = np.linspace(0, 1, m)[None, :]\n    out = np.stack([np.cos(a), np.zeros(n), np.sin(a)], 1)[:, None]\n    P = (r[:, None, None] * out + (lean * h)[:, None, None] * out * (s * s)[..., None]\n         + np.array([0, 1.0, 0]) * (h[:, None] * s)[..., None])\n    T = unit(np.gradient(P, axis=1))\n    C = lerp(rgb01((26, 86, 34)), rgb01((92, 172, 66)), s[..., None])\n    return Bits(P, T, np.broadcast_to(C, P.shape), T=T, thin=True)\n\n\nclass Garden:\n    \"\"\"grows the flowers over time, and hands back all their points for a moment.\"\"\"\n\n    def __init__(self):\n        self.flowers = []\n        for i, spec in enumerate(GARDEN):\n            radius = 0.012 if spec[\"kind\"] == \"lavender\" else 0.019 if spec[\"kind\"] == \"rose\" else 0.016\n            self.flowers.append(dict(spec, stem=Stem(spec[\"base\"], spec[\"top\"], radius), sets=head(spec[\"kind\"]),\n                                     phase=i * 1.7))\n        self.done = max(f[\"start\"] for f in GARDEN) + GROW * 0.85 + OPEN\n        self.cache, self.kept = None, {}              # finished flowers don't need rebuilding\n\n    def stage(self, f, t):\n        \"\"\"(stem grown 0-1, flower open 0-1) for one flower at time t.\"\"\"\n        return float(ease_out((t - f[\"start\"]) / GROW)), float(smooth((t - f[\"start\"] - GROW * 0.85) / OPEN))\n\n    def bloom(self, t):\n        return float(np.mean([self.stage(f, t)[1] for f in self.flowers]))\n\n    def points(self, t, res):\n        \"\"\"every point in the garden at time t, plus the tips still growing (for sparkles).\"\"\"\n        if t >= self.done and self.cache and self.cache[0] == res:\n            return self.cache[1], []\n        tuft = float(smooth(t / 1.4))\n        if tuft < 1 or (\"grass\", res) not in self.kept:\n            self.kept[(\"grass\", res)] = [grass(tuft, res)]\n        bits, tips, phase = list(self.kept[(\"grass\", res)]), [], [0.0]\n        for f in self.flowers:\n            g, b = self.stage(f, max(t, 0))\n            if g <= 0.01:\n                continue\n            start, key = len(bits), (f[\"kind\"], res)\n            if g >= 1 and b >= 1 and key in self.kept:\n                bits += self.kept[key]\n                phase += [f[\"phase\"]] * (len(bits) - start)\n                continue\n            stem = f[\"stem\"]\n            bits.append(stem.bits(g, res, 1.0))\n            wide = 0.12 if f[\"kind\"] == \"tulip\" else 0.095\n            rise = 68 if f[\"kind\"] == \"tulip\" else 32\n            for n, (at, turn, length) in enumerate(f[\"leaves\"]):\n                open_, lk = float(smooth((g - at) / 0.25)), (f[\"kind\"], n, res)\n                if open_ >= 1 and lk in self.kept:            # an open leaf never changes again\n                    bits.append(self.kept[lk])\n                elif open_ > 0:\n                    origin = stem.at([at])[0][0]\n                    bits.append(leaf(origin, math.radians(turn), rise, length, wide, 1.1, open_, res))\n                    if open_ >= 1:\n                        self.kept[lk] = bits[-1]\n            tip, tangent = stem.at([g])\n            tip, tangent = tip[0], tangent[0]\n            if g < 0.995:\n                tips.append(tip)\n            if f[\"kind\"] == \"lavender\":\n                bits += florets(stem, g, f[\"size\"])\n            else:\n                size = f[\"size\"] * (0.3 + 0.7 * float(smooth((g - 0.2) / 0.8)))\n                out = np.array([f[\"top\"][0], 0, f[\"top\"][2]])\n                out = out / np.linalg.norm(out) if np.linalg.norm(out) > 0.1 else np.array([0, 0, 1.0])\n                lean = math.radians(f[\"tilt\"])\n                rot = frame_for(unit(out * math.sin(lean) + np.array([0, math.cos(lean), 0]) + tangent * 0.3))\n                parts = [p.bits(b, res * size) for p in f[\"sets\"]]\n                if f[\"kind\"] == \"daisy\" and b > 0:\n                    parts.append(disk(b, res * size))\n                if f[\"kind\"] == \"lily\" and b > 0.15:\n                    parts += stamens(b, res * size)\n                for p in parts:                                   # head space -> the garden\n                    p.P = tip + size * (p.P @ rot)\n                    p.N, p.T = p.N @ rot, p.T @ rot\n                    bits.append(p)\n            if g >= 1 and b >= 1:\n                self.kept[key] = bits[start:]\n            phase += [f[\"phase\"]] * (len(bits) - start)\n        part, base = [], 0\n        for p in bits:                                            # one number per petal / leaf / stem\n            part.append(p.part + base)\n            base += int(p.part.max()) + 1 if len(p.part) else 1\n        out = (np.concatenate([b.P for b in bits]), np.concatenate([b.N for b in bits]),\n               np.concatenate([b.T for b in bits]), np.concatenate([b.C for b in bits]),\n               np.concatenate(part), np.concatenate([b.thin for b in bits]),\n               np.concatenate([b.shine for b in bits]),\n               np.concatenate([np.full(len(b.P), ph) for b, ph in zip(bits, phase)]))\n        if t >= self.done:\n            self.cache = (res, out)\n        return out, tips\n\n\n# ── light, camera, glyphs ───────────────────────────────────────────────────\nKEY = unit(np.array([-0.55, 0.65, 0.55]))        # main light: up, left, in front\nFILL = unit(np.array([0.7, 0.1, 0.4]))\nHALF = unit(KEY + np.array([0, 0, 1.0]))\nRAMP = np.array(list(\" .,:;=+*?%#&8$@\"))         # light to dense\nLINE = np.array(list(\"-/|\\\\\"))                   # by the slope of a thin stroke\nSUBX, SUBY = 2, 4                                # every cell is sampled 2 across x 4 down (square samples)\nQUADS = np.array([[0, 2], [1, 3], [4, 6], [5, 7]])   # the samples in each quarter: TL, TR, BL, BR\nGLYPH8 = SHAPE.reshape(len(SHAPE), 4, 2, 2, 2).mean((2, 4)).reshape(len(SHAPE), 8)   # glyphs at 2x4\nGLYPH8_E = (GLYPH8 ** 2).sum(1)\n\n\nclass View:\n    \"\"\"the camera, pointed at the garden and fitted to the art pane.\"\"\"\n\n    def __init__(self, ax, ay, aw, ah, cell, dither=False, room=(1, 5)):\n        self.ax, self.ay, self.aw, self.ah, self.cell = ax, ay, aw, ah, cell\n        # with only 256 colours, a fine 2x2 pattern of nudges hides the steps between shades\n        bayer = (np.array([[0, 2], [3, 1]]) / 4 - 0.375) * (0.1 if dither else 0.0)\n        cols = np.tile(np.arange(aw) % 2, ah)\n        rows = np.repeat(np.arange(ah) % 2, aw)\n        self.nudge = dict(top=bayer[0, cols], bottom=bayer[1, cols], left=bayer[rows, 0], right=bayer[rows, 1])\n        top, bottom = room[0], ah - room[1]           # room for the clock and the notes\n        tall = max(4, bottom - top)\n        self.k = min(aw * 0.94 / SPAN_X, tall * cell / SPAN_Y)   # cells per unit, sideways\n        self.cx, self.cy = aw / 2, top + tall / 2\n        self.res = min(1.6 * self.k, 90)              # points per unit: just enough to fill the cells\n        self.grain = np.random.default_rng(3).uniform(-0.45, 0.45, ah * aw)\n\n    def project(self, P, spin):\n        M = rot_x(TILT) @ rot_y(spin)\n        Q = (P - np.array([0, AIM_Y, 0])) @ M.T\n        f = DIST / (DIST - Q[:, 2])\n        return self.cx + Q[:, 0] * f * self.k, self.cy - Q[:, 1] * f * self.k / self.cell, DIST - Q[:, 2], M\n\n    def draw(self, scr, pts, t, spin, look):\n        \"\"\"paint the garden into the screen; returns the depth of every cell (inf = sky).\"\"\"\n        P, N, T, C, part, thin, shine, phase = pts\n        sway = 0.02 * P[:, 1] ** 2                    # a breeze, stronger up high\n        P = P + np.stack([sway * np.sin(1.25 * t + phase), np.zeros_like(sway),\n                          0.7 * sway * np.cos(1.05 * t + phase)], 1)\n        col, row, z, M = self.project(P, spin)\n        Nn, Tn = N @ M.T, T @ M.T\n\n        # light: two lamps, a shine, and a rim of light on the edges\n        face = np.abs(Nn[:, 2])\n        n2 = Nn * np.where(Nn[:, 2] < 0, -1.0, 1.0)[:, None]\n        spec = shine * np.clip(n2 @ HALF, 0, None) ** 24\n        lit = 0.26 + 0.66 * np.clip(n2 @ KEY, 0, None) + 0.26 * np.clip(n2 @ FILL, 0, None) + 0.38 * (1 - face) ** 2 + spec\n        rgb = np.clip(C * (0.35 + 0.8 * lit)[:, None] + 0.55 * spec[:, None], 0, 1)\n\n        # every cell is split into 2x4 square samples, and the nearest point in each sample wins.\n        # stems and grass are laid down two samples wide so they don't vanish\n        W, H = self.aw * SUBX, self.ah * SUBY\n        xi, yi = np.floor(col * SUBX).astype(np.int64), np.floor(row * SUBY).astype(np.int64)\n        src = np.concatenate([np.arange(len(z)), np.flatnonzero(thin)])\n        xi, yi = np.concatenate([xi, xi[thin] + 1]), np.concatenate([yi, yi[thin]])\n        ok = (xi >= 0) & (xi < W) & (yi >= 0) & (yi < H)\n        pix, who = yi[ok] * W + xi[ok], src[ok]\n        depth = np.full(W * H, np.inf)\n        np.minimum.at(depth, pix, z[who])\n        win = z[who] <= depth[pix]\n        owner = np.full(W * H, -1)\n        owner[pix[win]] = who[win]\n\n        # close pinholes: an empty sample between two full ones copies the nearer neighbour\n        o2, d2 = owner.reshape(H, W), depth.reshape(H, W)\n        for axis in (1, 0):\n            a, b = np.roll(o2, 1, axis), np.roll(o2, -1, axis)\n            da, db = np.roll(d2, 1, axis), np.roll(d2, -1, axis)\n            hole = (o2 < 0) & (a >= 0) & (b >= 0)\n            first = da <= db\n            o2, d2 = np.where(hole, np.where(first, a, b), o2), np.where(hole, np.where(first, da, db), d2)\n\n        # regroup sample by cell: (cells, 8)\n        def cellwise(x):\n            return x.reshape(self.ah, SUBY, self.aw, SUBX).transpose(0, 2, 1, 3).reshape(self.ah * self.aw, 8)\n\n        O8, D8 = cellwise(o2), cellwise(d2)\n        full = O8 >= 0\n        solid = full.any(1)\n        safe = np.where(full, O8, 0)\n        rgb8 = np.where(full[..., None], rgb[safe], 0.0)\n        y0, x0, cw, chh = self.ay, self.ax, self.aw, self.ah\n        out_ch, out_fg = scr.ch[y0: y0 + chh, x0: x0 + cw].ravel().copy(), scr.fg[y0: y0 + chh, x0: x0 + cw].ravel().copy()\n        out_bg = scr.bg[y0: y0 + chh, x0: x0 + cw].ravel().copy()\n\n        if look == \"hd\":\n            # two coloured pixels per cell: split top/bottom (▀) or left/right (▌), whichever fits\n            q = rgb8[:, QUADS].mean(2)                                    # TL, TR, BL, BR\n            top, bottom = (q[:, 0] + q[:, 1]) / 2, (q[:, 2] + q[:, 3]) / 2\n            left, right = (q[:, 0] + q[:, 2]) / 2, (q[:, 1] + q[:, 3]) / 2\n            miss_rows = ((q[:, :2] - top[:, None]) ** 2).sum((1, 2)) + ((q[:, 2:] - bottom[:, None]) ** 2).sum((1, 2))\n            miss_cols = ((q[:, ::2] - left[:, None]) ** 2).sum((1, 2)) + ((q[:, 1::2] - right[:, None]) ** 2).sum((1, 2))\n            upright = miss_cols < miss_rows * 0.8\n            nd, lit_ = self.nudge, lambda c: (c.max(1) > 0.03)[:, None]     # noqa: E731 - leave the sky black\n            ink = np.where(upright[:, None], left + nd[\"left\"][:, None] * lit_(left), top + nd[\"top\"][:, None] * lit_(top))\n            paper = np.where(upright[:, None], right + nd[\"right\"][:, None] * lit_(right),\n                             bottom + nd[\"bottom\"][:, None] * lit_(bottom))\n            out_ch[solid] = np.where(upright, \"▌\", \"▀\")[solid]\n            out_fg[solid] = pack(ink.T)[solid]\n            out_bg[solid] = pack(paper.T)[solid]\n        else:\n            # letters: each cell takes the glyph whose shape matches its front piece best\n            front = np.where(full, D8, np.inf).argmin(1)\n            fo = safe[np.arange(len(safe)), front]                       # the point in front, per cell\n            mine = full & (part[safe] == part[fo][:, None])\n            cov = mine.sum(1)\n            colour = (rgb8 * mine[..., None]).sum(1) / np.maximum(cov, 1)[:, None]\n            tone = np.clip(((lit[safe] * mine).sum(1) / np.maximum(cov, 1) - 0.15) / 0.8, 0, 1) ** 0.75\n            glyph = RAMP[np.clip(np.rint(tone * (len(RAMP) - 1) + self.grain), 1, len(RAMP) - 1).astype(int)]\n            partial = solid & (cov < 8)\n            glyph[partial] = CHARS[(GLYPH8_E[None, :] - 2 * (0.78 * mine[partial]) @ GLYPH8.T).argmin(1)]\n            # stems, grass and sheets seen edge-on: a stroke along their own direction\n            stroke = solid & (thin[fo] | (face[fo] < 0.12))\n            dx = np.where(thin[fo], Tn[fo, 0], -Nn[fo, 1])\n            dy = np.where(thin[fo], Tn[fo, 1], Nn[fo, 0])\n            slope = (np.degrees(np.arctan2(dy, dx)) + 202.5) % 180\n            glyph[stroke] = LINE[(slope[stroke] // 45).astype(int) % 4]\n            colour[stroke] *= 1.12\n            out_ch[solid], out_fg[solid] = glyph[solid], pack(np.clip(colour, 0, 1).T)[solid]\n\n        scr.ch[y0: y0 + chh, x0: x0 + cw] = out_ch.reshape(chh, cw)\n        scr.fg[y0: y0 + chh, x0: x0 + cw] = out_fg.reshape(chh, cw)\n        scr.bg[y0: y0 + chh, x0: x0 + cw] = out_bg.reshape(chh, cw)\n        return np.where(full, D8, np.inf).min(1).reshape(chh, cw)\n\n\n# ── the sky ─────────────────────────────────────────────────────────────────\ndef moon(scr, ax, ay, aw, ah, cell, hd=False):\n    \"\"\"a thin crescent up in the corner: letters, or two soft pixels per cell in hd.\"\"\"\n    R = float(np.clip(aw * 0.07, 3, 8))\n    mx, my = ax + aw * 0.17, ay + ah * 0.12 + 1\n    ys, xs = np.mgrid[int(my - R / cell) - 1: int(my + R / cell) + 2, int(mx - R) - 1: int(mx + R) + 2]\n    keep = (ys >= ay) & (ys < ay + ah) & (xs >= ax) & (xs < ax + aw)\n    ys, xs = ys[keep], xs[keep]\n    free = (scr.ch[ys, xs] == \" \") & (scr.bg[ys, xs] == 0)\n    ys, xs = ys[free], xs[free]\n    tint = np.array([0.96, 0.92, 0.74])[:, None]\n\n    def light(fy):                                      # how much moon covers a point, and how bright\n        dx, dy = (xs + 0.5 - mx) / R, (ys + fy - my) * cell / R\n        inside = smooth((1 - np.sqrt(dx * dx + dy * dy)) * R * 1.5)\n        shadow = smooth((np.sqrt((dx - 0.42) ** 2 + (dy + 0.12) ** 2) - 0.9) * R * 1.5)\n        return inside * shadow, np.clip(0.55 - dx, 0, 1)\n\n    if hd:\n        (a_top, s_top), (a_bot, s_bot) = light(0.25), light(0.75)\n        on = (a_top + a_bot) > 0.05\n        scr.ch[ys[on], xs[on]] = \"▀\"\n        scr.fg[ys[on], xs[on]] = pack(tint * (a_top * (0.55 + 0.45 * s_top))[on])\n        scr.bg[ys[on], xs[on]] = pack(tint * (a_bot * (0.55 + 0.45 * s_bot))[on])\n    else:\n        a, shade = light(0.5)\n        on = a > 0.5\n        scr.ch[ys[on], xs[on]] = np.array(list(\":*%&@\"))[np.clip((shade[on] * 5).astype(int), 0, 4)]\n        scr.fg[ys[on], xs[on]] = pack(tint * (0.55 + 0.45 * shade[on]))\n\n\nclass Sky:\n    \"\"\"shooting stars, fireflies, and the glitter thrown off by growing stems.\"\"\"\n\n    def __init__(self):\n        self.rng = np.random.default_rng(7)\n        self.comet, self.next_comet = None, 3.0\n        n = 16\n        self.fly = dict(r=self.rng.uniform(0.35, 0.95, n), y=self.rng.uniform(0.25, 1.6, n),\n                        w=self.rng.uniform(0.15, 0.4, n) * self.rng.choice([-1, 1], n),\n                        a=self.rng.uniform(0, TAU, n), blink=self.rng.uniform(0, TAU, n))\n        self.dust = np.zeros((0, 7))                  # x y z vx vy vz age\n\n    def sparkle(self, tips, dt):\n        if tips:\n            k = len(tips) * 3\n            p = np.repeat(np.array(tips), 3, 0)\n            v = self.rng.normal(0, 0.18, (k, 3)) + np.array([0, 0.25, 0])\n            self.dust = np.concatenate([self.dust, np.c_[p, v, np.zeros(k)]])[-260:]\n        if len(self.dust):\n            self.dust[:, 3:6] *= 1 - 0.8 * dt\n            self.dust[:, 4] -= 0.35 * dt\n            self.dust[:, :3] += self.dust[:, 3:6] * dt\n            self.dust[:, 6] += dt\n            self.dust = self.dust[self.dust[:, 6] < 1.3]\n\n    def draw(self, scr, view, depth, t, spin):\n        ax, ay, aw, ah = view.ax, view.ay, view.aw, view.ah\n        # a shooting star now and then\n        if self.comet is None and t > self.next_comet:\n            go = self.rng.choice([-1, 1])\n            self.comet = (t, ax + aw * self.rng.uniform(0.2, 0.8), ay + ah * self.rng.uniform(0.05, 0.3),\n                          go * self.rng.uniform(28, 40), self.rng.uniform(9, 14))\n        if self.comet:\n            t0, x0, y0, vx, vy = self.comet\n            age = t - t0\n            for k in range(14):\n                a = age - k * 0.018\n                x, y = int(x0 + vx * a), int(y0 + vy * a / view.cell * 0.7)\n                if a < 0 or not (ax <= x < ax + aw and ay <= y < ay + ah) or scr.ch[y, x] != \" \":\n                    continue\n                fade = max(0.0, 1 - k / 14) * max(0.0, 1 - age / 1.1)\n                scr.ch[y, x] = \"*\" if k == 0 else (\"\\\\\" if vx > 0 else \"/\") if k < 5 else \".\"\n                scr.fg[y, x] = pack(np.array([0.85, 0.9, 1.0]) * fade)\n            if age > 1.1:\n                self.comet, self.next_comet = None, t + self.rng.uniform(4, 8)\n\n        # fireflies drifting round the garden, and fresh glitter\n        f = self.fly\n        ang = f[\"a\"] + f[\"w\"] * t\n        flies = np.stack([f[\"r\"] * np.cos(ang), f[\"y\"] + 0.08 * np.sin(t * 0.9 + f[\"blink\"]), f[\"r\"] * np.sin(ang)], 1)\n        glow = 0.5 + 0.5 * np.sin(t * 2.2 + f[\"blink\"])\n        self._dots(scr, view, depth, flies, 0.0, glow, np.array([1.0, 0.9, 0.45]))\n        if len(self.dust):\n            life = 1 - self.dust[:, 6] / 1.3\n            self._dots(scr, view, depth, self.dust[:, :3], spin, life, np.array([1.0, 0.95, 0.85]))\n\n    @staticmethod\n    def _dots(scr, view, depth, P, spin, bright, tint):\n        col, row, z, _ = view.project(P, spin)\n        ci, ri = np.floor(col).astype(int), np.floor(row).astype(int)\n        ok = (ci >= 0) & (ci < view.aw) & (ri >= 0) & (ri < view.ah) & (bright > 0.15)\n        ci, ri, z, b = ci[ok], ri[ok], z[ok], bright[ok]\n        front = z < depth[ri, ci]\n        ci, ri, b = ci[front], ri[front], b[front]\n        scr.ch[view.ay + ri, view.ax + ci] = np.where(b > 0.75, \"*\", np.where(b > 0.45, \"+\", \".\"))\n        scr.fg[view.ay + ri, view.ax + ci] = pack(tint[:, None] * (0.35 + 0.65 * b))\n\n\n# ── keys, notes, music, and the loop ────────────────────────────────────────\nclass Song(Sound):\n    \"\"\"the garden's music, on repeat (art.py's Sound, but looping).\"\"\"\n\n    def __init__(self, ff, path):\n        fd, self.wav = tempfile.mkstemp(prefix=\"garden_\", suffix=\".wav\")\n        os.close(fd)\n        self.extract = subprocess.Popen(                 # no seeking: that would drop the first 23 ms\n            [ff, \"-nostdin\", \"-loglevel\", \"error\", \"-y\", \"-i\", path, \"-ac\", \"2\", \"-ar\", \"44100\",\n             \"-c:a\", \"pcm_s16le\", self.wav], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n        self.ok, self.proc = None, None\n\n    def play(self):\n        if not self.ready():\n            return\n        if os.name == \"nt\":\n            import winsound\n            winsound.PlaySound(self.wav, winsound.SND_FILENAME | winsound.SND_ASYNC | winsound.SND_LOOP\n                               | winsound.SND_NODEFAULT)\n            return\n        player = shutil.which(\"ffplay\")\n        if player:\n            self.proc = subprocess.Popen([player, \"-nodisp\", \"-loop\", \"0\", \"-loglevel\", \"quiet\", self.wav],\n                                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n        else:\n            super().play()                            # (afplay / aplay: once through)\n\n\nclass Keys(Terminal):\n    \"\"\"the terminal from art.py, but arrow keys come back as names.\"\"\"\n\n    def key(self):\n        if os.name == \"nt\":\n            import msvcrt\n            if not msvcrt.kbhit():\n                return \"\"\n            ch = msvcrt.getwch()\n            if ch in (\"\\x00\", \"\\xe0\"):\n                return {\"K\": \"left\", \"M\": \"right\", \"H\": \"up\", \"P\": \"down\"}.get(msvcrt.getwch(), \"\")\n            return ch\n        if self.saved is not None:\n            import select\n            if select.select([sys.stdin], [], [], 0)[0]:\n                ch = os.read(sys.stdin.fileno(), 1).decode(errors=\"ignore\")\n                if ch == \"\\x1b\" and select.select([sys.stdin], [], [], 0.02)[0]:\n                    seq = os.read(sys.stdin.fileno(), 8).decode(errors=\"ignore\")\n                    return {\"[A\": \"up\", \"[B\": \"down\", \"[C\": \"right\", \"[D\": \"left\"}.get(seq[:2], \"\")\n                return ch\n        return \"\"\n\n\nclass Show:\n    \"\"\"one terminal-sized picture of everything: garden, sky, notes, code.\"\"\"\n\n    def __init__(self, size, show_code, cell, colours, cps):\n        W, H = size\n        self.scr = Screen(W, H, colours)\n        self.lay = Layout(W, H, SPAN_X / SPAN_Y, show_code, cell)\n        self.view = View(*self.lay.art, cell, dither=colours == 256)\n        self.stars, self.code, self.cell = Stars(), Code(os.path.abspath(__file__), cps), cell\n\n    def compose(self, garden, sky, t, spin, speed, paused, fps, tag, script, look=\"hd\", song=False):\n        scr, v = self.scr, self.view\n        scr.clear()\n        pts, tips = garden.points(t, v.res)\n        depth = v.draw(scr, pts, t, spin, look)\n        moon(scr, v.ax, v.ay, v.aw, v.ah, self.cell, hd=look == \"hd\")\n        self.stars.draw(scr, v.ax, v.ay, v.aw, v.ah, t)\n        sky.draw(scr, v, depth, t, spin)\n        cells = int(np.isfinite(depth).sum())\n        drawn = f\"pixels {2 * cells:,}\" if look == \"hd\" else f\"letters {cells:,}\"\n\n        ax, ay, aw, ah = self.lay.art\n        stamp = f\" t {t:05.2f}s\"\n        scr.put(ax + aw - len(stamp) - 2, ay, \"■\", C_PINK)\n        scr.put(ax + aw - len(stamp) - 1, ay, stamp, C_PINK)\n        way = \"||\" if paused else \">>\" if speed > 0.005 else \"<<\" if speed < -0.005 else \"  \"\n        bar = int(round(abs(speed) / MAX_SPIN * 10))\n        notes = (f\"{tag} · {time.localtime().tm_year}\" + (f\"   ♪ {CREDIT}\" if song else \"\"),\n                 f\"bloom {100 * garden.bloom(t):5.1f}%   spin {speed:+.2f} turns/s {way}\",\n                 f\"{drawn}   [{'=' * bar}{'-' * (10 - bar)}]\",\n                 \"up/dn speed  <-/-> push  space pause  r flip  g regrow  m look\")\n        for i, text in enumerate(notes):\n            scr.put(ax + 1, ay + ah - 4 + i, text, C_HUD if i < 3 else C_RULE + 0x262630)\n        sx, sy, sw = self.lay.status\n        scr.put(sx, sy, f\"$ py {script}\", C_STATUS)\n        right = f\"running · {fps:.0f} fps\"\n        scr.put(sx + sw - len(right) - 1, sy, right, C_HUD)\n        if self.lay.code:\n            x, y, w, h = self.lay.code\n            scr.put(x, y - 1, \"─\" * w, C_RULE)\n            self.code.draw(scr, x, y, w, h, t)\n        return tips\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=\"a garden grows in the terminal, then spins\")\n    ap.add_argument(\"--speed\", type=float, default=0.25, help=\"spin, in turns per second (negative = other way)\")\n    ap.add_argument(\"--look\", choices=(\"letters\", \"hd\"), default=\"letters\",\n                    help=\"letters = glyph art like the rose, hd = two shaded pixels per character\")\n    ap.add_argument(\"--no-code\", action=\"store_true\", help=\"hide the code pane\")\n    ap.add_argument(\"--tag\", default=\"a little garden\", help='the credit line, e.g. \"@yourname\"')\n    ap.add_argument(\"--fps\", type=float, default=30.0)\n    ap.add_argument(\"--cps\", type=float, default=170.0, help=\"typing speed of the code pane\")\n    ap.add_argument(\"--cell\", type=float, default=2.0, help=\"height / width of one terminal cell\")\n    ap.add_argument(\"--colours\", \"--colors\", choices=(\"auto\", \"24\", \"256\"), default=\"auto\")\n    ap.add_argument(\"--mute\", action=\"store_true\", help=\"no music\")\n    ap.add_argument(\"--song\", default=SONG, help=\"the music (loops); reflections.m4a by default\")\n    args = ap.parse_args()\n\n    song = None\n    if not args.mute and os.path.isfile(args.song):\n        try:\n            song = Song(find_ffmpeg(), args.song)       # unpacked to a wav while the window opens\n        except SystemExit:                            # no ffmpeg: the garden grows in silence\n            song = None\n    term, garden, sky = Keys(), Garden(), Sky()\n    colours, show_code = Terminal.colours(args.colours), not args.no_code\n    script = os.path.basename(sys.argv[0]) or \"flowers.py\"\n    chosen, look = float(np.clip(args.speed, -MAX_SPIN, MAX_SPIN)), args.look\n    show = size = None\n    speed = spin = 0.0\n    paused, fps, frames = False, args.fps, 0\n    start = last = time.perf_counter()\n    try:\n        term.open()\n        if song:\n            song.play()\n            start = last = time.perf_counter()        # the garden's clock starts with the music\n        while not term.dead:\n            key = term.key()\n            k = key.lower()\n            if k in (\"q\", \"\\x1b\", \"\\x03\"):\n                break\n            way = 1.0 if chosen >= 0 else -1.0\n            if key == \"up\" or k in (\"+\", \"=\", \"w\"):                  # faster, whichever way it turns\n                chosen = way * min(MAX_SPIN, round(abs(chosen) + 0.05, 2))\n            if key == \"down\" or k in (\"-\", \"_\", \"s\"):                # slower, down to a standstill\n                chosen = way * max(0.0, round(abs(chosen) - 0.05, 2))\n            if key == \"right\" or k == \"d\":                           # push it round to the right\n                chosen = min(MAX_SPIN, round(chosen + 0.05, 2))\n            if key == \"left\" or k == \"a\":                            # or to the left\n                chosen = max(-MAX_SPIN, round(chosen - 0.05, 2))\n            if k == \"r\":\n                chosen = -chosen\n            if k == \" \":\n                paused = not paused\n            if k == \"g\":                              # back to bare soil, and the song from the top\n                if song:\n                    song.stop()\n                    song.play()\n                start, spin, speed, sky = time.perf_counter(), 0.0, 0.0, Sky()\n            if k == \"c\":\n                show_code, size = not show_code, None\n            if k == \"m\":\n                look = \"letters\" if look == \"hd\" else \"hd\"\n            if term.size() != size:\n                size = term.size()\n                show = Show(size, show_code, args.cell, colours, args.cps)\n                term.write(\"\\x1b[0m\\x1b[2J\")\n\n            now = time.perf_counter()\n            dt, last = min(now - last, 0.1), now\n            t = max(0.0, now - start - (LEAD if song else 0.0))\n            grown = t > garden.done + 0.4\n            target = 0.0 if (paused or not grown) else chosen\n            speed += (target - speed) * min(1.0, dt * 2.5)    # ease into any change of speed\n            spin += speed * TAU * dt\n            fps += (1 / max(dt, 1e-3) - fps) * 0.1\n\n            tips = show.compose(garden, sky, t, spin, speed, paused, fps, args.tag, script, look, song is not None)\n            sky.sparkle(tips, dt)\n            term.write(show.scr.flush())\n            frames += 1\n            wait = 1 / args.fps - (time.perf_counter() - now)\n            if wait > 0:\n                time.sleep(wait)\n    except KeyboardInterrupt:\n        pass\n    finally:\n        term.close()\n        if song:\n            song.close()\n    secs = time.perf_counter() - start\n    if frames and secs > 0:\n        print(f\"drew {frames} frames in {secs:.1f}s  ({frames / secs:.1f} fps)\")\n\n\nif __name__ == \"__main__\":\n    main()\n", "builtins": ["ArithmeticError", "AssertionError", "AttributeError", "BaseException", "BaseExceptionGroup", "BlockingIOError", "BrokenPipeError", "BufferError", "BytesWarning", "ChildProcessError", "ConnectionAbortedError", "ConnectionError", "ConnectionRefusedError", "ConnectionResetError", "DeprecationWarning", "EOFError", "Ellipsis", "EncodingWarning", "EnvironmentError", "Exception", "ExceptionGroup", "False", "FileExistsError", "FileNotFoundError", "FloatingPointError", "FutureWarning", "GeneratorExit", "IOError", "ImportError", "ImportWarning", "IndentationError", "IndexError", "InterruptedError", "IsADirectoryError", "KeyError", "KeyboardInterrupt", "LookupError", "MemoryError", "ModuleNotFoundError", "NameError", "None", "NotADirectoryError", "NotImplemented", "NotImplementedError", "OSError", "OverflowError", "PendingDeprecationWarning", "PermissionError", "ProcessLookupError", "PythonFinalizationError", "RecursionError", "ReferenceError", "ResourceWarning", "RuntimeError", "RuntimeWarning", "StopAsyncIteration", "StopIteration", "SyntaxError", "SyntaxWarning", "SystemError", "SystemExit", "TabError", "TimeoutError", "True", "TypeError", "UnboundLocalError", "UnicodeDecodeError", "UnicodeEncodeError", "UnicodeError", "UnicodeTranslateError", "UnicodeWarning", "UserWarning", "ValueError", "Warning", "WindowsError", "ZeroDivisionError", "_IncompleteInputError", "__build_class__", "__debug__", "__doc__", "__import__", "__loader__", "__name__", "__package__", "__spec__", "abs", "aiter", "all", "anext", "any", "ascii", "bin", "bool", "breakpoint", "bytearray", "bytes", "callable", "chr", "classmethod", "compile", "complex", "copyright", "credits", "delattr", "dict", "dir", "divmod", "enumerate", "eval", "exec", "exit", "filter", "float", "format", "frozenset", "getattr", "globals", "hasattr", "hash", "help", "hex", "id", "input", "int", "isinstance", "issubclass", "iter", "len", "license", "list", "locals", "map", "max", "memoryview", "min", "next", "np", "object", "oct", "open", "ord", "pow", "print", "property", "quit", "range", "repr", "reversed", "round", "self", "set", "setattr", "slice", "sorted", "staticmethod", "str", "sum", "super", "tuple", "type", "vars", "zip"]};
